import re


class CycleError(Exception):
    pass


_TOKEN_RE = re.compile(
    r"(?P<num>\d+(?:\.\d+)?|\.\d+)"
    r"|(?P<ref>[A-Za-z]+[0-9]*)"
    r"|(?P<op>[+\-*/()])"
)


def _tokenize(text):
    tokens = []
    pos = 0
    while pos < len(text):
        if text[pos].isspace():
            pos += 1
            continue
        m = _TOKEN_RE.match(text, pos)
        if not m:
            raise ValueError(f"unexpected character at position {pos}: {text[pos:]!r}")
        tokens.append((m.lastgroup, m.group()))
        pos = m.end()
    return tokens


class _Parser:
    """Recursive-descent parser/evaluator.

    expr   := term (('+' | '-') term)*
    term   := factor (('*' | '/') factor)*
    factor := ('-' | '+') factor | '(' expr ')' | number | cellref
    """

    def __init__(self, tokens, resolve):
        self.tokens = tokens
        self.pos = 0
        self.resolve = resolve  # cell name -> float

    def _peek(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return (None, None)

    def _next(self):
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def parse(self):
        value = self._expr()
        if self.pos != len(self.tokens):
            raise ValueError(f"unexpected trailing token: {self._peek()[1]!r}")
        return value

    def _expr(self):
        value = self._term()
        while self._peek() in (("op", "+"), ("op", "-")):
            op = self._next()[1]
            rhs = self._term()
            value = value + rhs if op == "+" else value - rhs
        return value

    def _term(self):
        value = self._factor()
        while self._peek() in (("op", "*"), ("op", "/")):
            op = self._next()[1]
            rhs = self._factor()
            value = value * rhs if op == "*" else value / rhs
        return value

    def _factor(self):
        kind, val = self._peek()
        if (kind, val) == ("op", "-"):
            self._next()
            return -self._factor()
        if (kind, val) == ("op", "+"):
            self._next()
            return self._factor()
        if (kind, val) == ("op", "("):
            self._next()
            value = self._expr()
            if self._next() != ("op", ")"):
                raise ValueError("expected ')'")
            return value
        if kind == "num":
            self._next()
            return float(val)
        if kind == "ref":
            self._next()
            return self.resolve(val)
        raise ValueError(f"unexpected token: {val!r}")


def evaluate(cells):
    """Compute every cell's float value, resolving references transitively."""
    values = {}
    visiting = set()  # cells on the current resolution stack (for cycle detection)

    def resolve(name):
        if name in values:
            return values[name]
        if name in visiting:
            raise CycleError(f"dependency cycle involving {name!r}")
        if name not in cells:
            raise KeyError(f"reference to undefined cell {name!r}")
        visiting.add(name)
        try:
            values[name] = _compute(name)
        finally:
            visiting.discard(name)
        return values[name]

    def _compute(name):
        text = cells[name]
        if isinstance(text, str) and text.startswith("="):
            return float(_Parser(_tokenize(text[1:]), resolve).parse())
        return float(text)

    for name in cells:
        resolve(name)
    return values

